import{c as e,Q as a,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const g=JSON.parse('{"title":"ShiftLeft","description":"","frontmatter":{},"headers":[{"level":1,"title":"ShiftLeft","slug":"shiftleft"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/逻辑计算/ShiftLeft-35.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/逻辑计算/ShiftLeft-35.md"}'),d={name:"api/SIMD-API/基础API/Reg矢量计算/逻辑计算/ShiftLeft-35.md"};function r(i,t,l,p,o,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="shiftleft" tabindex="-1">ShiftLeft <a class="header-anchor" href="#shiftleft" aria-label="Permalink to &quot;ShiftLeft&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>根据mask，对输入数据srcReg0，按照srcReg1对应元素进行左移操作，并将结果写入dstReg。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, typename U = DefaultType, MaskMergeMode mode = MaskMergeMode::ZEROING, typename S, typename V&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void ShiftLeft(S&amp; dstReg, S&amp; srcReg0, V&amp; srcReg1, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/uint32_t/int32_t/uint64_t/int64_t</td></tr><tr><td>U</td><td>左移参数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t/int16_t/int32_t/int64_t 源操作数和目的操作数的数据类型约束参考表3 源操作数和目的操作数的数据类型约束。</td></tr><tr><td>mode</td><td>选择MERGING模式或ZEROING模式。 ZEROING，mask未选中的元素在dst中置零。MERGING，当前不支持。</td></tr><tr><td>S</td><td>srcReg0/dstReg的RegTensor类型， 例如RegTensor&lt;uint32_t&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>V</td><td>srcReg1的RegTensor类型， 例如RegTensor&lt;int32_t&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg0</td><td>输入</td><td>源操作数。 类型为RegTensor。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>srcReg1</td><td>输入</td><td>源操作数。 类型为RegTensor。 不支持设置为负数。</td></tr><tr><td>mask</td><td>输入</td><td>源操作数元素操作的有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><p><strong>表 3</strong> 源操作数和目的操作数的数据类型约束</p><table tabindex="0"><thead><tr><th>srcReg0/dstReg数据类型</th><th>srcReg1数据类型</th></tr></thead><tbody><tr><td>uint8_t</td><td>int8_t</td></tr><tr><td>uint16_t</td><td>int16_t</td></tr><tr><td>uint32_t</td><td>int32_t</td></tr><tr><td>uint64_t</td><td>int64_t</td></tr><tr><td>int8_t</td><td>int8_t</td></tr><tr><td>int16_t</td><td>int16_t</td></tr><tr><td>int32_t</td><td>int32_t</td></tr><tr><td>int64_t</td><td>int64_t</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>对于逻辑位移（无符号数据类型），如果位移量大于数据类型位宽，则输出为0。</li><li>对于算术位移（有符号数据类型），如果srcReg0小于0，srcReg1小于0，并且位移量大于数据类型位宽，则输出-1；如果srcReg0大于0，并且位移量大于数据类型位宽，则输出0。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void ShiftLeftVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ U* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;U&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg1, src1Addr + i * oneRepeatSize);       </span></span>
<span class="line"><span>        AscendC::Reg::ShiftLeft(dstReg, srcReg0, srcReg1, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,20)])])}const _=e(d,[["render",r]]);export{g as __pageData,_ as default};
